import numpy as np

class Connect4:
    """
    Connect 4 game logic.
    """

    def __init__(self, size=6):
        """
        Initialize a new Connect4 instance.

        Args:
            size (int, optional): The size of the board. Defaults to 6.
        """
        self.size = size
        self.board = np.zeros((size, size), dtype=int)

    def play(self, column, player=1):
        """
        Play a move in the game.

        Args:
            column (int): The column to drop the piece.
            player (int, optional): The player to make the move. Defaults to 1.
        """
        if 0 <= column < self.size and np.all(self.board[:, column] == 0):
            for row in range(self.size - 1, -1, -1):
                if self.board[row][column] == 0:
                    self.board[row][column] = player
                    break
            else:
                raise ValueError("Column is full")

    def check_winner(self, player=1):
        """
        Check who has won the game.

        Args:
            player (int, optional): The player to check. Defaults to 1.

        Returns:
            int: The winning player, or 0 if there is no winner.
        """
        for row in range(self.size):
            for col_start in range(self.size - 1):
                if self.board[row][col_start] == player:
                    for col in range(col_start + 1, self.size):
                        if self.board[row][col] == player:
                            return player
                        elif self.board[row][col] == 0:
                            break
                elif self.board[row][col_start] == 0:
                    break

        for col in range(self.size):
            for row_start in range(self.size - 1):
                if self.board[row_start][col] == player:
                    for row in range(row_start + 1, self.size):
                        if self.board[row][col] == player:
                            return player
                        elif self.board[row][col] == 0:
                            break
                elif self.board[row_start][col] == 0:
                    break

        diagonal_top_left = all(
            self.board[i][i] == player for i in range(self.size)
        ) or all(self.board[i][self.size - i - 1] == player for i in range(self.size))

        if diagonal_top_left:
            return player

        diagonal_bottom_left = all(
            self.board[i][i] == player for i in range(self.size)
        ) or all(self.board[i][self.size - i - 1] == player for i in range(self.size))

        if diagonal_bottom_left:
            return player

        return 0

    def is_full(self):
        """
        Check if the board is full.

        Returns:
            bool: True if the board is full, False otherwise.
        """
        return np.all(self.board!= 0)

    def display(self):
        """
        Display the current state of the board.
        """
        for row in self.board:
            print(" | ".join(str(cell) for cell in row))
            print("-" * (self.size * 3 + 1))
```

