def extract_values(nested_dict, keys_to_extract):
    """
    Extracts multiple values from a nested dictionary.

    Args:
        nested_dict (dict): The dictionary to extract values from.
        keys_to_extract (list): A list of keys to extract from the nested dictionary.

    Returns:
        dict: A new dictionary containing the extracted values.

    Raises:
        KeyError: If any key in keys_to_extract is not found in the nested dictionary.

    Example:
        nested_dict = {
            'a': 1,
            'b': {
                'c': 2,
                'd': 3,
                'e': {
                    'f': 4,
                    'g': 5
                }
            },
            'h': 6
        }

        keys_to_extract = ['b.e.f', 'a', 'h']

        result = extract_values(nested_dict, keys_to_extract)
        print(result)  # Output: {'b.e.f': 4, 'a': 1, 'h': 6}
    """
    extracted_values = {}

    for key in keys_to_extract:
        key_parts = key.split('.')
        value = nested_dict

        for part in key_parts:
            value = value.get(part)

            if value is None:
                raise KeyError(f"Key '{key}' not found in the nested dictionary.")

    for key in keys_to_extract:
        extracted_values[key] = nested_dict.get(key)

    return extracted_values
```

